function steer(s) {
  const clamp = (v, min, max) => Math.max(min, Math.min(max, v));

  const front = Math.max(1, s.front);
  const left = Math.max(1, s.left);
  const right = Math.max(1, s.right);
  const speed = s.speed;

  // Estimate road direction from diagonal wall distances.
  const leftBias = left - front;
  const rightBias = right - front;

  // Positive means steer right.
  let turn = (rightBias - leftBias) / 100;

  // Stronger correction when approaching a wall.
  const dangerLeft = clamp((65 - left) / 65, 0, 1);
  const dangerRight = clamp((65 - right) / 65, 0, 1);

  turn += (dangerLeft - dangerRight) * 1.8;

  // Anticipate sharp turns using diagonal clearance.
  const asymmetry = left - right;
  turn += clamp(asymmetry / 120, -1, 1) * 0.65;

  turn = clamp(turn, -1, 1);

  // Slow down when the road ahead narrows or steering is aggressive.
  const cornering = Math.abs(turn);
  const dangerFront = clamp((75 - front) / 75, 0, 1);
  const targetSpeed = 10 - cornering * 7 - dangerFront * 6;

  let gas = speed > targetSpeed
    ? 0.1
    : clamp(0.55 + (targetSpeed - speed) * 0.15, 0.2, 1);

  // Emergency wall avoidance.
  if (left < 27 || right < 27 || front < 25) {
    gas = 0;
    if (left < right) turn = 1;
    else if (right < left) turn = -1;
  }

  return {
    turn: clamp(turn, -1, 1),
    gas: clamp(gas, 0, 1)
  };
}

function steer(s) {
  const { front, left, right, speed } = s;

  // Centering & corner-entry steering
  // Steer toward whichever side has more open space, scaled by how tight the road is
  const diff = right - left;
  const sideSum = Math.max(1, left + right);
  const lateralError = diff / sideSum;

  // Increase steering authority as front wall approaches
  const urgency = Math.max(0.6, Math.min(2.2, 220 / Math.max(25, front)));
  let turn = lateralError * urgency * 1.8;

  // Emergency wall-avoidance override (car is 20px wide -> 10px radius)
  if (left < 32) {
    turn += ((32 - left) / 32) * 1.5;
  }
  if (right < 32) {
    turn -= ((32 - right) / 32) * 1.5;
  }

  // Hairpin / dead-end commitment: if front is very close and sides are nearly equal, commit hard
  if (front < 75 && Math.abs(diff) < 12) {
    turn = right >= left ? 1 : -1;
  }

  turn = Math.max(-1, Math.min(1, turn));

  // Speed management: target speed proportional to clear distance ahead and inverse to turn sharpness
  const safeStoppingDist = speed * speed * 2.1 + 28;
  const cornerTargetSpeed = Math.max(2.6, Math.min(10, (front / 26) * (1 - 0.55 * Math.abs(turn))));

  let gas;
  if (front < safeStoppingDist && speed > cornerTargetSpeed) {
    // Active braking (< 0.2 brakes) scaled by how overspeed we are
    const overshoot = (speed - cornerTargetSpeed) / 10;
    gas = Math.max(0, 0.18 - overshoot * 0.4);
  } else if (speed > cornerTargetSpeed + 0.5) {
    // Coasting (0.2 to 0.45 maintains/gently bleeds speed without harsh braking)
    gas = 0.25;
  } else {
    // Full throttle on straights, smooth power out of corners
    gas = Math.max(0.55, Math.min(1, (cornerTargetSpeed - speed + 2) / 3));
  }

  return { turn, gas };
}

function steer(s) {
  const st = steer.state || (steer.state = { turn: 0 });
  if (s.speed < 0.5 && s.front > 150) st.turn = 0; // reset on fresh start

  const { left, right, front, speed } = s;
  const roadWidth = left + right;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  // Center on the road
  let target = ((right - left) / Math.max(roadWidth, 1)) * 2.2;

  // Wall repulsion
  if (left < 35)  target += (35 - left)  / 35 * 0.9;
  if (right < 35) target -= (35 - right) / 35 * 0.9;

  // Look-ahead: steer toward the more open side as the wall approaches
  if (front < 110) target += (right - left) / 90;
  if (front < 55)  target *= 1.5;
  target = clamp(target, -1, 1);

  // Adaptive smoothing: react faster when the wall is close
  const alpha = front < 80 ? 0.7 : 0.35;
  const turn = st.turn * (1 - alpha) + target * alpha;
  st.turn = turn;

  // Speed planning: pick a target speed from available room and upcoming turn
  const room = clamp(front / 180, 0, 1);
  const sharpness = Math.abs(target);              // leading indicator
  const narrow = clamp((140 - roadWidth) / 140, 0, 1);
  const targetSpeed = 3 + 9 * room * (1 - 0.6 * sharpness) * (1 - 0.4 * narrow);

  // Proportional speed control (tune the 0.5 gain)
  let gas = clamp((targetSpeed - speed) * 0.5 + 0.3, 0, 1);

  // Hard lift when too fast for the room ahead
  if (front < 70 && speed > 4) gas = 0;
  // Never stall from a standstill
  if (speed < 1.5) gas = Math.max(gas, 0.35);

  return { turn, gas };
}

function steer(s) {
  const f = s.front;
  const l = s.left;
  const r = s.right;
  const v = s.speed;
  const dx = 0.7071 * (r - l);
  const dy = f + 0.7071 * (l + r);
  const angle = Math.atan2(dx, dy);
  let turn = angle * (2.8 + Math.max(0, 140 - f) / 70) + (r - l) / 220;
  if (l < 28 && r < 28) {
    turn = r >= l ? 1 : -1;
  } else {
    if (l < 28) turn = Math.max(turn, 1 - l / 40);
    if (r < 28) turn = Math.min(turn, -1 + r / 40);
  }
  if (f < 35) {
    turn = Math.max(-1, Math.min(1, turn * 1.5));
    if (Math.abs(turn) < 0.8) turn = r >= l ? 1 : -1;
  }
  turn = Math.max(-1, Math.min(1, turn));
  let target = Math.min(1.5 + f * 0.02125, 10 - Math.abs(turn) * 7);
  if (Math.min(l, r) < 30) target = Math.min(target, 2.2);
  if (f < 25) target = Math.min(target, 1.4);
  let gas = 0.2 + (target - v) * 0.35;
  gas = Math.max(0, Math.min(1, gas));
  return { turn, gas };
}

function steer(s) {
  steer.state = steer.state || { turn: 0, speed: 0 };

  const left = s.left, right = s.right, front = s.front;
  const roadWidth = left + right;

  // Aim for the center of the visible road.
  const centerError = (right - left) / Math.max(roadWidth, 1);
  let targetTurn = centerError * 2.2;

  // If one side is open and the other is closing, steer away from the wall.
  if (left < 35) targetTurn += (35 - left) / 35 * 0.9;
  if (right < 35) targetTurn -= (35 - right) / 35 * 0.9;

  // Avoid the wall ahead.
  if (front < 110) targetTurn += (right - left) / 90;
  if (front < 55) targetTurn *= 1.5;

  // Smooth steering to avoid oscillation.
  const turn = steer.state.turn * 0.65 + Math.max(-1, Math.min(1, targetTurn)) * 0.35;
  steer.state.turn = turn;

  // Corner severity: strong steering or narrow road means slow down.
  const corner = Math.abs(turn);
  const narrow = Math.max(0, (140 - roadWidth) / 50);

  let gas = 1;
  if (front < 180) gas -= (180 - front) / 180 * 0.75;
  gas -= corner * 0.55;
  gas -= narrow * 0.35;

  // Brake harder when very close to a wall or in a sharp turn.
  if (front < 70) gas = Math.min(gas, 0.05);
  if (corner > 0.55 && s.speed > 4) gas = Math.min(gas, 0.1);

  return { turn, gas: Math.max(0, Math.min(1, gas)) };
}
